examples.template:
MonarchSplitButton(
    text = {{label}},
    onClick = {},
    arrowIcon = {
        MonarchIcon(SampleIcons.ChevronDown, contentDescription = null, size = MonarchIconSize.Sm)
    },
    variant = MonarchButtonVariant.{{variant|pascal}},
) { close ->
    MonarchMenuItem(text = {{items.0}}, onClick = close)
    MonarchMenuItem(text = {{items.1}}, onClick = close)
}

